"""Redact credential-like fields from spine and export payloads (#48)."""

from __future__ import annotations

from typing import Any

REDACTED = "[redacted]"

# Usage counters — not credentials.
_KEEP_KEYS = frozenset({"tokens", "token_count", "total_tokens", "max_tokens"})

_SECRET_KEYS = frozenset(
    {
        "api_key",
        "apikey",
        "password",
        "passwd",
        "secret",
        "secret_value",
        "private_key",
        "authorization",
        "access_token",
        "refresh_token",
        "client_secret",
        "card_number",
        "cvv",
        "pan",
        "pin",
        "credential",
        "credentials",
        "bearer",
        "auth_token",
        "api_token",
        "session_token",
        "id_token",
        "token",
    }
)

_SECRET_SUFFIXES = ("_token", "_secret", "_password", "_api_key", "_private_key")

# Do not treat these as inject/secret channels even if named "token".
_MIN_SCRUB_LEN = 8


def secret_like_key(key: str) -> bool:
    """True when a mapping key should never appear with a live value on the spine."""
    raw = str(key)
    lowered = raw.lower().replace("-", "_")
    if lowered in _KEEP_KEYS:
        return False
    if lowered in _SECRET_KEYS:
        return True
    return any(lowered.endswith(suffix) for suffix in _SECRET_SUFFIXES)


def strip_secret_like_keys(data: dict[str, Any]) -> dict[str, Any]:
    """Drop credential-like keys from a live args dict (agent-supplied tokens are ignored)."""
    out: dict[str, Any] = {}
    for key, value in data.items():
        if secret_like_key(str(key)):
            continue
        if isinstance(value, dict):
            out[key] = strip_secret_like_keys(value)
        else:
            out[key] = value
    return out


def _scrub_string(text: str, secret_values: set[str]) -> str:
    out = text
    for value in sorted(secret_values, key=len, reverse=True):
        if len(value) >= _MIN_SCRUB_LEN and value in out:
            out = out.replace(value, REDACTED)
    return out


def redact_payload(
    payload: Any,
    *,
    secret_values: set[str] | None = None,
) -> Any:
    """Deep-copy payload replacing secret keys and known live secret substrings."""
    secrets = {str(item) for item in (secret_values or set()) if item}
    return _redact(payload, secrets)


def _redact(value: Any, secrets: set[str]) -> Any:
    if isinstance(value, dict):
        out: dict[str, Any] = {}
        for key, inner in value.items():
            if secret_like_key(str(key)):
                out[key] = REDACTED
            else:
                out[key] = _redact(inner, secrets)
        return out
    if isinstance(value, list):
        return [_redact(item, secrets) for item in value]
    if isinstance(value, tuple):
        return tuple(_redact(item, secrets) for item in value)
    if isinstance(value, str) and secrets:
        return _scrub_string(value, secrets)
    return value

"""Redact operator PII for export surfaces."""

from __future__ import annotations

import copy
from typing import Any

from aura.config import get_config

DEFAULT_REDACT_FIELDS = frozenset({"email", "name", "phone"})


def identity_export_settings() -> tuple[bool, frozenset[str]]:
    cfg = get_config().values
    export_pii = bool(cfg.get("identity_export_pii", False))
    raw = cfg.get("identity_redact_fields")
    if isinstance(raw, list):
        fields = frozenset(str(x) for x in raw)
    else:
        fields = DEFAULT_REDACT_FIELDS
    return export_pii, fields


def redact_operator_dict(
    operator: dict[str, Any], *, export_pii: bool, fields: frozenset[str]
) -> dict[str, Any]:
    if export_pii or not operator:
        return dict(operator)
    redacted = dict(operator)
    for key in fields:
        if key in redacted:
            redacted[key] = None
    if "subject" in redacted and "subject_hash" not in redacted:
        from aura.identity.models import hash_subject

        redacted["subject_hash"] = hash_subject(str(redacted["subject"]))
    return redacted


def redact_agent_ids(agent_ids: dict[str, Any] | None) -> dict[str, Any]:
    if not agent_ids:
        return {}
    export_pii, fields = identity_export_settings()
    if export_pii:
        return dict(agent_ids)
    out = copy.deepcopy(agent_ids)
    ids = out.get("ids")
    if isinstance(ids, dict) and isinstance(ids.get("operator"), dict):
        ids["operator"] = redact_operator_dict(
            ids["operator"], export_pii=export_pii, fields=fields
        )
    return out


def redact_summary(summary: dict[str, Any]) -> dict[str, Any]:
    export_pii, fields = identity_export_settings()
    if export_pii:
        return summary
    out = copy.deepcopy(summary)
    agent_ids = out.get("agent_ids")
    if isinstance(agent_ids, dict):
        out["agent_ids"] = redact_agent_ids(agent_ids)
    identity = out.get("identity")
    if isinstance(identity, dict) and isinstance(identity.get("operator"), dict):
        identity["operator"] = redact_operator_dict(
            identity["operator"], export_pii=export_pii, fields=fields
        )
    return out

"""Secret brokers — resolve credential refs at egress, never store values on profiles (#48)."""

from __future__ import annotations

import os
from typing import Any, Callable, Mapping, Protocol, runtime_checkable


class SecretBrokerError(Exception):
    """Base class for capability secret resolution failures."""


class SecretConfigError(SecretBrokerError, ValueError):
    """Profile or broker configuration tried to hold a plaintext secret."""


class SecretNotFoundError(SecretBrokerError):
    """Broker could not resolve a declared secret ref."""

    def __init__(self, ref: str) -> None:
        self.ref = ref
        super().__init__(f"Secret ref not resolved: {ref}")


@runtime_checkable
class SecretBroker(Protocol):
    """Resolve a capability secret reference to a live credential."""

    def resolve(self, ref: str) -> str: ...


def normalize_secret_ref(ref: str) -> str:
    """Trim a ref; keep provider prefix (``env:NAME``, ``vault:path``, …)."""
    text = str(ref).strip()
    if not text:
        raise SecretConfigError("secret ref must be a non-empty string")
    return text


def env_key_from_ref(ref: str) -> str:
    """Map ``env:NAME`` / ``NAME`` to an environment variable name."""
    text = normalize_secret_ref(ref)
    if text.lower().startswith("env:"):
        return text.split(":", 1)[1].strip()
    if ":" in text:
        return text
    return text


class EnvSecretBroker:
    """Resolve ``env:VAR`` (or bare ``VAR``) from process environment."""

    def __init__(self, *, environ: Mapping[str, str] | None = None) -> None:
        self._environ = environ

    def resolve(self, ref: str) -> str:
        key = env_key_from_ref(ref)
        source = self._environ if self._environ is not None else os.environ
        value = source.get(key)
        if value is None or value == "":
            raise SecretNotFoundError(ref)
        return str(value)


class MapSecretBroker:
    """In-memory map for tests and host-local vault shims. Never persist on a profile."""

    def __init__(self, mapping: Mapping[str, str]) -> None:
        self._mapping = {str(key): str(value) for key, value in mapping.items()}

    def resolve(self, ref: str) -> str:
        text = normalize_secret_ref(ref)
        if text in self._mapping:
            return self._mapping[text]
        key = env_key_from_ref(text)
        if key in self._mapping:
            return self._mapping[key]
        alt = f"env:{key}"
        if alt in self._mapping:
            return self._mapping[alt]
        raise SecretNotFoundError(ref)


class CallableSecretBroker:
    """Wrap a host callback (Vault, KMS, or test double)."""

    def __init__(self, resolver: Callable[[str], str | None]) -> None:
        self._resolver = resolver

    def resolve(self, ref: str) -> str:
        text = normalize_secret_ref(ref)
        value = self._resolver(text)
        if value is None or value == "":
            raise SecretNotFoundError(ref)
        return str(value)


class ChainSecretBroker:
    """Try brokers in order; first successful resolve wins."""

    def __init__(self, brokers: list[SecretBroker]) -> None:
        if not brokers:
            raise SecretConfigError("ChainSecretBroker requires at least one broker")
        self._brokers = list(brokers)

    def resolve(self, ref: str) -> str:
        last: SecretNotFoundError | None = None
        for broker in self._brokers:
            try:
                return broker.resolve(ref)
            except SecretNotFoundError as exc:
                last = exc
                continue
        if last is not None:
            raise last
        raise SecretNotFoundError(ref)


def broker_kind(broker: SecretBroker | None) -> str:
    if broker is None:
        return "none"
    return type(broker).__name__


def default_secret_broker(profile: Any | None = None) -> SecretBroker:
    """
    Env broker by default. Profile ``types`` with ``role: auth`` may select ``env``.

    Map/callable brokers cannot be declared in profile JSON (they would embed values).
    Bind those at ``session(secret_broker=...)``.
    """
    types = list(getattr(profile, "types", None) or []) if profile is not None else []
    for entry in types:
        if not isinstance(entry, dict):
            continue
        role = str(entry.get("role") or "").strip().lower()
        if role != "auth":
            continue
        config = entry.get("config") if isinstance(entry.get("config"), dict) else {}
        provider = str(config.get("provider") or config.get("broker") or "env").strip().lower()
        if provider in {"env", "environment"}:
            return EnvSecretBroker()
        raise SecretConfigError(
            "profile types role=auth cannot bind a map or callable broker; "
            "pass secret_broker= on agent.session() instead"
        )
    return EnvSecretBroker()

"""Operator identity models."""

from __future__ import annotations

from dataclasses import dataclass, field
from hashlib import sha256
from typing import Any


def hash_subject(subject: str) -> str:
    return sha256(subject.encode("utf-8")).hexdigest()[:16]


@dataclass
class OperatorIdentity:
    """Verified or declared operator attached to a session."""

    verified: bool
    method: str
    subject: str
    email: str | None = None
    name: str | None = None
    session_ref: str | None = None
    issuer: str | None = None
    claims: dict[str, Any] = field(default_factory=dict)

    def to_operator_dict(self) -> dict[str, Any]:
        data: dict[str, Any] = {
            "verified": self.verified,
            "method": self.method,
            "subject": self.subject,
            "subject_hash": hash_subject(self.subject),
        }
        if self.email:
            data["email"] = self.email
        if self.name:
            data["name"] = self.name
        if self.session_ref:
            data["session_ref"] = self.session_ref
        if self.issuer:
            data["issuer"] = self.issuer
        return data

    def bind_payload(self) -> dict[str, Any]:
        payload = {"operator": self.to_operator_dict()}
        if self.claims:
            payload["claim_keys"] = sorted(self.claims.keys())
        return payload

"""Agent registry — ULID ids, agent_ref, aliases, no identity service."""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any

from aura.agents.profile import AgentProfile
from aura.config import get_config
from aura.core.ids import is_legacy_aura_id, new_ulid, tenant_from_ref, validate_agent_ref


def _normalize_capabilities(raw: Any) -> list[dict[str, Any]]:
    from aura.core.capabilities import normalize_capabilities_for_store

    if raw is None:
        return []
    return normalize_capabilities_for_store(raw)


class DuplicateAgentError(ValueError):
    pass


class AgentNotFoundError(KeyError):
    pass


class AgentRegistry:
    """Local address book with ULID internal ids and stable agent_ref."""

    def __init__(self, base_dir: Path | None = None) -> None:
        cfg = get_config()
        self.base_dir = base_dir or cfg.registry_dir()
        self.base_dir.mkdir(parents=True, exist_ok=True)
        self._state_path = cfg.state_file()
        self._state = self._load_state()

    def _load_state(self) -> dict[str, Any]:
        if self._state_path.is_file():
            with self._state_path.open(encoding="utf-8") as f:
                data = json.load(f)
        else:
            data = {"aliases": {}, "refs": {}}
        data.setdefault("aliases", {})
        data.setdefault("refs", {})
        return data

    def _save_state(self) -> None:
        self._state_path.parent.mkdir(parents=True, exist_ok=True)
        with self._state_path.open("w", encoding="utf-8") as f:
            json.dump(self._state, f, indent=2)

    def _agent_path(self, aura_id: str) -> Path:
        safe = aura_id.replace("/", "_")
        return self.base_dir / f"{safe}.json"

    def _register_alias(self, name: str, aura_id: str) -> None:
        aliases: dict[str, str] = self._state.setdefault("aliases", {})
        existing = aliases.get(name)
        if existing and existing != aura_id:
            raise DuplicateAgentError(f"Agent name already in use: {name}")
        aliases[name] = aura_id
        self._save_state()

    def _remove_aliases(self, aura_id: str, *, keep: str | None = None) -> None:
        aliases: dict[str, str] = self._state.setdefault("aliases", {})
        removed = [
            name for name, mapped_id in aliases.items() if mapped_id == aura_id and name != keep
        ]
        for name in removed:
            del aliases[name]
        if removed:
            self._save_state()

    def _register_ref(self, agent_ref: str, aura_id: str) -> None:
        refs: dict[str, str] = self._state.setdefault("refs", {})
        existing = refs.get(agent_ref)
        if existing and existing != aura_id:
            raise DuplicateAgentError(f"agent_ref already in use: {agent_ref}")
        refs[agent_ref] = aura_id
        self._save_state()

    def create(
        self,
        name: str | None = None,
        *,
        agent_ref: str | None = None,
        aura_id: str | None = None,
        purpose: str | None = None,
        policy_version: str = "1",
        variables: dict[str, Any] | None = None,
        rules: list[dict[str, Any]] | None = None,
        skills: list[str] | None = None,
        sequencer: dict[str, Any] | None = None,
        observers: list[dict[str, Any]] | None = None,
        escalations: list[dict[str, Any]] | None = None,
        spectrum: dict[str, Any] | None = None,
        capabilities: list[dict[str, Any]] | None = None,
        types: list[dict[str, Any]] | None = None,
        ids: dict[str, Any] | None = None,
        default_mode: str = "script",
    ) -> AgentProfile:
        merged_ids = dict(ids or {})
        ref = validate_agent_ref(agent_ref) if agent_ref else None
        if not ref and name and "/" in name:
            ref = validate_agent_ref(name)

        if name:
            aliases: dict[str, str] = self._state.get("aliases", {})
            if name in aliases and not self.get_by_id(aliases[name]).archived:
                raise DuplicateAgentError(f"Agent name already in use: {name}")
        if ref:
            refs: dict[str, str] = self._state.get("refs", {})
            if ref in refs and not self.get_by_id(refs[ref]).archived:
                raise DuplicateAgentError(f"agent_ref already in use: {ref}")

        if aura_id:
            if self._agent_path(aura_id).is_file():
                raise DuplicateAgentError(f"aura_id already exists: {aura_id}")
            assigned_id = aura_id
        else:
            assigned_id = new_ulid()

        tenant = tenant_from_ref(ref)
        if tenant and "tenant" not in merged_ids:
            merged_ids["tenant"] = tenant

        profile = AgentProfile(
            aura_id=assigned_id,
            agent_ref=ref,
            name=name,
            ids=merged_ids,
            purpose=purpose,
            policy_version=str(policy_version),
            variables=variables or {},
            rules=rules or [],
            skills=skills or [],
            sequencer=sequencer,
            observers=observers or [],
            escalations=escalations or [],
            spectrum=dict(spectrum) if isinstance(spectrum, dict) else None,
            capabilities=_normalize_capabilities(capabilities),
            types=types or [],
            default_mode=default_mode,
        )
        self.save(profile)
        if name:
            self._register_alias(name, assigned_id)
        if ref:
            self._register_ref(ref, assigned_id)
        return profile

    def save(self, profile: AgentProfile) -> None:
        path = self._agent_path(profile.aura_id)
        with path.open("w", encoding="utf-8") as f:
            json.dump(profile.to_dict(), f, indent=2)

    def profile_path(self, aura_id: str) -> Path:
        return self._agent_path(aura_id)

    def update_profile(self, key: str, **updates: Any) -> AgentProfile:
        """Apply partial updates to an existing agent profile."""
        profile = self.resolve(key)
        aura_id = profile.aura_id

        if "name" in updates and updates["name"] is not None:
            new_name = updates["name"]
            if new_name != profile.name:
                self._register_alias(new_name, aura_id)
                self._remove_aliases(aura_id, keep=new_name)
                profile.name = new_name

        if "agent_ref" in updates:
            new_ref_raw = updates["agent_ref"]
            new_ref = validate_agent_ref(new_ref_raw) if new_ref_raw else None
            old_ref = profile.agent_ref
            refs: dict[str, str] = self._state.setdefault("refs", {})
            if old_ref and refs.get(old_ref) == aura_id and old_ref != new_ref:
                del refs[old_ref]
                self._save_state()
            if new_ref:
                self._register_ref(new_ref, aura_id)
            profile.agent_ref = new_ref
            tenant = tenant_from_ref(new_ref)
            if tenant:
                profile.ids.setdefault("tenant", tenant)

        if "purpose" in updates and updates["purpose"] is not None:
            profile.purpose = updates["purpose"]
        if "policy_version" in updates and updates["policy_version"] is not None:
            profile.policy_version = str(updates["policy_version"])
        if "default_mode" in updates and updates["default_mode"] is not None:
            profile.default_mode = updates["default_mode"]
        if updates.get("skills") is not None:
            profile.skills = list(updates["skills"])
        if updates.get("variables") is not None:
            profile.variables.update(dict(updates["variables"]))
        if updates.get("ids") is not None:
            profile.ids.update(dict(updates["ids"]))
        if updates.get("rules") is not None:
            profile.rules = list(updates["rules"])
        if "spectrum" in updates:
            raw = updates["spectrum"]
            profile.spectrum = dict(raw) if isinstance(raw, dict) else None
        if updates.get("capabilities") is not None:
            profile.capabilities = _normalize_capabilities(updates["capabilities"])

        self.save(profile)
        return profile

    def get_by_id(self, aura_id: str) -> AgentProfile:
        path = self._agent_path(aura_id)
        if not path.is_file() and is_legacy_aura_id(aura_id):
            path = self.base_dir / f"{aura_id}.json"
        if not path.is_file():
            raise AgentNotFoundError(aura_id)
        with path.open(encoding="utf-8") as f:
            return AgentProfile.from_dict(json.load(f))

    def get_by_name(self, name: str) -> AgentProfile:
        aliases: dict[str, str] = self._state.get("aliases", {})
        aura_id = aliases.get(name)
        if not aura_id:
            raise AgentNotFoundError(name)
        return self.get_by_id(aura_id)

    def get_by_ref(self, agent_ref: str) -> AgentProfile:
        ref = validate_agent_ref(agent_ref)
        refs: dict[str, str] = self._state.get("refs", {})
        aura_id = refs.get(ref)
        if not aura_id:
            raise AgentNotFoundError(agent_ref)
        return self.get_by_id(aura_id)

    def resolve(self, key: str) -> AgentProfile:
        """Lookup by agent_ref, name alias, or aura_id."""
        try:
            return self.get_by_ref(key)
        except AgentNotFoundError:
            pass
        try:
            return self.get_by_name(key)
        except AgentNotFoundError:
            pass
        return self.get_by_id(key)

    def get_or_create(self, name: str, **kwargs: Any) -> AgentProfile:
        try:
            return self.resolve(name)
        except AgentNotFoundError:
            return self.create(name=name, **kwargs)

    def list_agents(self, include_archived: bool = False) -> list[AgentProfile]:
        profiles: list[AgentProfile] = []
        for path in sorted(self.base_dir.glob("*.json")):
            with path.open(encoding="utf-8") as f:
                profile = AgentProfile.from_dict(json.load(f))
            if profile.archived and not include_archived:
                continue
            profiles.append(profile)
        return profiles

    def archive(self, aura_id: str) -> AgentProfile:
        profile = self.get_by_id(aura_id)
        profile.archived = True
        self.save(profile)
        self._remove_aliases(aura_id)
        refs: dict[str, str] = self._state.get("refs", {})
        if profile.agent_ref and refs.get(profile.agent_ref) == aura_id:
            del refs[profile.agent_ref]
        self._save_state()
        return profile
